fn an_unknown_named_provider_has_no_fabricated_provenance() {
    let client = formal_ai::CachedSourceClient::new(
        std::env::temp_dir().join("formal-ai-source-qualified-definition-offline"),
        formal_ai::CurlSourceTransport,
